    def collect_dynamic_structs(self, decls):
        structs = {}
        def add_fields(name, fields):
            if not name:
                return
            key = self.safe_name(name)
            cur = structs.setdefault(key, {'name': key, 'fields': [], 'seen': set()})
            for f in fields:
                fname = self.safe_name(f.name)
                if fname in cur['seen']:
                    continue
                nf = copy.copy(f); nf.name = fname
                cur['fields'].append(nf); cur['seen'].add(fname)
        def walk(nodes):
            for n in nodes:
                if isinstance(n, DynamicStructDecl):
                    add_fields(n.name, n.fields)
                elif isinstance(n, DynamicStructExpand):
                    add_fields(n.name, n.fields)
                elif isinstance(n, Function):
                    walk(n.body)
                elif isinstance(n, ClassDecl):
                    for m in n.methods: walk(m.body)
                    for child in n.nested: walk([child])
                elif isinstance(n, If):
                    walk(n.then_body); walk(n.else_body)
                elif isinstance(n, While):
                    walk(n.body)
                elif isinstance(n, DoWhile):
                    walk(n.body)
                elif isinstance(n, For):
                    walk(n.body)
                elif isinstance(n, TryCatch):
                    walk(n.try_body)
                    for _, body in n.catches: walk(body)
        walk(decls)
        return structs

    def dynamic_struct_block(self, structs):
        lines = []
        for name in sorted(structs.keys()):
            info = structs[name]
            lines.append(f'typedef struct {name} {{')
            for f in info['fields']:
                lines.append('  ' + self.c_decl(f.type_name, self.safe_name(f.name)) + ';')
            lines.append(f'}} {name};')
            lines.append('')
        return lines

    def collect_global_vars(self, decls):
        globals_out = []
        seen = set()
        def add(v):
            key = (self.package_name(getattr(v, 'package', DEFAULT_PACKAGE)), self.safe_name(v.name))
            if key in seen:
                return
            seen.add(key)
            globals_out.append(v)
        def walk(nodes):
            for n in nodes:
                if isinstance(n, VarDecl) and getattr(n, 'global_decl', False):
                    add(n)
                elif isinstance(n, Function):
                    walk(getattr(n, 'body', []) or [])
                elif isinstance(n, ClassDecl):
                    for m in getattr(n, 'methods', []) or []:
                        walk(getattr(m, 'body', []) or [])
                    for child in getattr(n, 'nested', []) or []:
                        walk([child])
                elif isinstance(n, If):
                    walk(n.then_body); walk(n.else_body)
                elif isinstance(n, While):
                    walk(n.body)
                elif isinstance(n, DoWhile):
                    walk(n.body)
                elif isinstance(n, For):
                    walk(n.body)
                elif isinstance(n, TryCatch):
                    walk(n.try_body)
                    for _, body in n.catches:
                        walk(body)
        walk(decls)
        return globals_out

    def camel_to_snake(self, name):
        s = re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', str(name or ''))
        s = re.sub(r'([A-Z]+)([A-Z][a-z])', r'\1_\2', s)
        out = self.safe_name(s).lower()
        out = out.replace('i_pv4', 'ipv4').replace('i_pv6', 'ipv6').replace('i_cmp', 'icmp')
        return out

    def lower_sys_calls(self, s):
        ns_map = {'Stdio':'stdio', 'IO':'io', 'Algorithms':'algorithms', 'STL':'stl'}
        def repl(m):
            ns = ns_map.get(m.group(1), self.camel_to_snake(m.group(1)))
            fn = self.camel_to_snake(m.group(2))
            # Route new Stdio calls to the compatibility wrapper; legacy generated
            # names are left available for existing examples.
            if ns == 'stdio' and fn in {'print','println'}:
                return f'cmotive_sys_stdio_{fn}_new('
            return f'cmotive_sys_{ns}_{fn}('
        return re.sub(r'\bSys\s*::\s*([A-Za-z_]\w*)\s*::\s*([A-Za-z_]\w*)\s*\(', repl, s)

    # ---------- template instantiation ----------
    def scan_decls(self, decls):
        for d in decls:
            self.scan_node(d)

    def scan_node(self, node):
        if isinstance(node, TemplateDecl):
            return
        if isinstance(node, ClassDecl):
            if node.base: self.scan_text(node.base)
            for b, _ in node.bases: self.scan_text(b)
            for f in node.fields:
                self.scan_text(f.type_name); self.scan_text(f.initial or '')
            for m in node.methods: self.scan_node(m)
            for n in node.nested: self.scan_node(n)
        elif isinstance(node, Function):
            self.scan_text(node.return_type)
            for p in node.params:
                self.scan_text(p.type_name); self.scan_text(p.default or '')
            for s in node.body: self.scan_node(s)
        elif isinstance(node, DynamicStructDecl):
            for f in node.fields:
                self.scan_text(f.type_name); self.scan_text(f.initial or '')
        elif isinstance(node, VarDecl):
            self.scan_text(node.type_name); self.scan_text(node.value or '')
        elif isinstance(node, Return): self.scan_text(node.value)
        elif isinstance(node, ExprStmt): self.scan_text(node.value)
        elif isinstance(node, If):
            self.scan_text(node.condition); self.scan_decls(node.then_body); self.scan_decls(node.else_body)
        elif isinstance(node, While): self.scan_text(node.condition); self.scan_decls(node.body)
        elif isinstance(node, DoWhile): self.scan_text(node.condition); self.scan_decls(node.body)
        elif isinstance(node, For): self.scan_text(node.header); self.scan_decls(node.body)
        elif isinstance(node, Throw): self.scan_text(node.value)
        elif isinstance(node, TargetStmt):
            self.scan_text(node.sender); self.scan_text(node.object_expr); self.scan_text(node.args); self.scan_text(node.hit_id)
        elif isinstance(node, DynamicStructExpand):
            for f in node.fields:
                self.scan_text(f.type_name); self.scan_text(f.initial or '')
        elif isinstance(node, TryCatch):
            self.scan_decls(node.try_body)
            for spec, body in node.catches:
                self.scan_text(spec); self.scan_decls(body)
        elif isinstance(node, RawStmt): self.scan_text(node.value)
        elif isinstance(node, RawDecl): self.scan_text(node.value)

    def scan_text(self, text):
        if not text:
            return
        for name, args in self.find_template_uses(str(text)):
            if name in self.templates:
                key = (name, tuple(args))
                if key not in self.template_use_seen:
                    self.template_use_seen.add(key)
                    self.template_use_queue.append(key)

    def find_template_uses(self, text):
        uses = []
        for m in re.finditer(r'\b([A-Za-z_]\w*)\s*<\s*([^<>]+?)\s*>', text):
            name = m.group(1)
            args = self.split_template_args(m.group(2))
            if args:
                uses.append((name, args))
        return uses

    def split_template_args(self, arg_text):
        args, cur, depth = [], [], 0
        for ch in arg_text:
            if ch == '<': depth += 1
            elif ch == '>': depth -= 1
            if ch == ',' and depth == 0:
                val = ''.join(cur).strip()
                if val: args.append(val)
                cur = []
            else:
                cur.append(ch)
        val = ''.join(cur).strip()
        if val: args.append(val)
        return args

    def instantiate_all(self):
        while self.template_use_queue:
            name, args = self.template_use_queue.pop(0)
            templ = self.templates.get(name)
            if not templ or len(args) != len(templ.params):
                continue
            if templ.kind == 'class' and templ.body_node:
                inst_name = self.template_instance_name(name, args)
                if inst_name in self.class_instances:
                    continue
                mapping = {p.name: a for p, a in zip(templ.params, args)}
                cls = self.clone_class_template(templ.body_node, inst_name, mapping)
                self.class_instances[inst_name] = cls
                self.scan_node(cls)
            elif templ.kind == 'function' and templ.body_node:
                inst_name = self.template_instance_name(name, args)
                if inst_name in self.function_instances:
                    continue
                mapping = {p.name: a for p, a in zip(templ.params, args)}
                fn = self.clone_function_template(templ.body_node, inst_name, mapping)
                self.function_instances[inst_name] = fn
                self.scan_node(fn)

    def template_instance_name(self, name, args):
        return self.safe_name(name) + '__' + '__'.join(self.safe_name(self.canonical_type_for_symbol(a)) for a in args)

    def canonical_type_for_symbol(self, t):
        t = self.normalize_template_text(t)
        t = t.replace('::', '_')
        t = re.sub(r'\s+', '', t)
        t = t.replace('*', 'Ptr').replace('&', 'Ref')
        t = t.replace('<', '__').replace('>', '').replace(',', '__')
        return t or 'Type'

    def normalize_template_text(self, t):
        return re.sub(r'\s+', ' ', str(t or '').strip())

    def substitute_type(self, t, mapping):
        s = str(t or '')
        for k, v in mapping.items():
            s = re.sub(r'\b' + re.escape(k) + r'\b', v, s)
        return s

    def substitute_expr(self, text, mapping):
        return self.substitute_type(text, mapping)

    def clone_class_template(self, cls, inst_name, mapping):
        fields = []
        for f in cls.fields:
            nf = copy.copy(f)
            nf.type_name = self.substitute_type(f.type_name, mapping)
            nf.initial = self.substitute_expr(f.initial, mapping) if f.initial is not None else None
            fields.append(nf)
        methods = []
        for m in cls.methods:
            nm = self.clone_function_template(m, m.name, mapping)
            nm.method_of = inst_name
            methods.append(nm)
        nested = [self.clone_class_template(n, inst_name + '__' + n.name, mapping) for n in cls.nested]
        bases = [(self.substitute_type(b, mapping), v) for b, v in cls.bases]
        base = self.substitute_type(cls.base, mapping) if cls.base else None
        return ClassDecl(inst_name, base, methods, fields, cls.has_virtuals, bases, nested, getattr(cls, 'package', DEFAULT_PACKAGE))

    def clone_function_template(self, fn, inst_name, mapping):
        params = [Param(p.name, self.substitute_type(p.type_name, mapping), self.substitute_expr(p.default, mapping) if p.default else None) for p in fn.params]
        body = [self.clone_stmt(s, mapping) for s in fn.body]
        return Function(inst_name, params, body, self.substitute_type(fn.return_type, mapping), fn.method_of, list(fn.decorators), fn.constructor, fn.destructor, fn.pure_virtual, getattr(fn, 'package', DEFAULT_PACKAGE))

    def clone_stmt(self, s, mapping):
        if isinstance(s, VarDecl):
            ns = copy.copy(s); ns.type_name = self.substitute_type(s.type_name, mapping); ns.value = self.substitute_expr(s.value, mapping); return ns
        if isinstance(s, Return): return Return(self.substitute_expr(s.value, mapping))
        if isinstance(s, ExprStmt): return ExprStmt(self.substitute_expr(s.value, mapping))
        if isinstance(s, If): return If(self.substitute_expr(s.condition, mapping), [self.clone_stmt(x, mapping) for x in s.then_body], [self.clone_stmt(x, mapping) for x in s.else_body])
        if isinstance(s, While): return While(self.substitute_expr(s.condition, mapping), [self.clone_stmt(x, mapping) for x in s.body])
        if isinstance(s, DoWhile): return DoWhile([self.clone_stmt(x, mapping) for x in s.body], self.substitute_expr(s.condition, mapping))
        if isinstance(s, For): return For(self.substitute_expr(s.header, mapping), [self.clone_stmt(x, mapping) for x in s.body])
        if isinstance(s, Throw): return Throw(self.substitute_expr(s.value, mapping))
        if isinstance(s, TargetStmt):
            return TargetStmt(self.substitute_expr(s.sender, mapping), self.substitute_expr(s.object_expr, mapping), self.substitute_expr(s.args, mapping), self.substitute_expr(s.hit_id, mapping))
        if isinstance(s, DynamicStructExpand):
            fields = []
            for f in s.fields:
                nf = copy.copy(f); nf.type_name = self.substitute_type(f.type_name, mapping); fields.append(nf)
            return DynamicStructExpand(s.name, fields)
        if isinstance(s, TryCatch): return TryCatch([self.clone_stmt(x, mapping) for x in s.try_body], [(self.substitute_expr(spec, mapping), [self.clone_stmt(x, mapping) for x in body]) for spec, body in s.catches])
        if isinstance(s, RawStmt): return RawStmt(self.substitute_expr(s.value, mapping))
        return copy.copy(s)

    # ---------- lifecycle and class metadata ----------
    def ensure_lifecycle_methods(self, classes):
        for c in classes:
            has_zero_ctor = any(m.constructor and len(m.params) == 0 for m in c.methods)
            if not has_zero_ctor:
                c.methods.insert(0, Function(c.name, [], [], 'Void', c.name, constructor=True, package=getattr(c, 'package', DEFAULT_PACKAGE)))
            if not any(m.destructor for m in c.methods):
                c.methods.append(Function('~' + c.name, [], [], 'Void', c.name, destructor=True, package=getattr(c, 'package', DEFAULT_PACKAGE)))
            for m in c.methods:
                if not getattr(m, 'package', None):
                    m.package = getattr(c, 'package', DEFAULT_PACKAGE)
            for n in c.nested:
                self.ensure_lifecycle_methods([n])

    def order_classes_by_base(self, classes):
        pending = list(classes)
        emitted = set()
        ordered = []
        while pending:
            moved = False
            next_pending = []
            for c in pending:
                b = self.safe_name(c.base) if c.base else None
                if not b or b in emitted or c.base not in {x.name for x in classes} and b not in {self.safe_name(x.name) for x in classes}:
                    ordered.append(c)
                    emitted.add(self.safe_name(c.name))
                    moved = True
                else:
                    next_pending.append(c)
            if not moved:
                ordered.extend(next_pending)
                break
            pending = next_pending
        return ordered

    def collect_ctor_arg_counts(self, classes):
        counts = {}
        for c in classes:
            cname = self.safe_name(c.name)
            counts[cname] = set()
            for m in c.methods:
                if m.constructor:
                    counts[cname].add(len(m.params))
        return counts

    def collect_ctor_signatures(self, classes):
        sigs = {}
        for c in classes:
            cname = self.safe_name(c.name)
            entries = []
            for m in c.methods:
                if m.constructor:
                    types = tuple(self.canonical_type(p.type_name) for p in m.params)
                    entries.append((types, m))
            sigs[cname] = entries
            sigs[c.name] = entries
        return sigs

    def canonical_type(self, t):
        s = self.normalize_type_string(t or 'I32')
        alias = {
            'Int16':'I16', 'Int32':'I32', 'Int':'I64',
            'Uint16':'U16', 'Uint32':'U32', 'Uint':'U64',
            'boolean':'Boolean', 'Bool':'Boolean', 'void':'Void', 'char':'Char',
            'float':'Float', 'double':'Double'
        }
        ptr = ''
        while s.endswith('*') or s.endswith('&'):
            ptr = '*' + ptr
            s = s[:-1].strip()
        s = alias.get(s, s)
        return s + ptr

    def type_symbol_suffix(self, t):
        return self.safe_name(self.canonical_type_for_symbol(self.canonical_type(t)))

    def constructor_name_for_types(self, class_name, types, package=None):
        base = f'{self.class_symbol_prefix(class_name, package)}__ctor'
        types = tuple(self.canonical_type(t) for t in (types or ()))
        return base if not types else base + '__' + '__'.join(self.type_symbol_suffix(t) for t in types)

    def new_name_for_types(self, class_name, types, package=None):
        base = f'{self.class_symbol_prefix(class_name, package)}__new'
        types = tuple(self.canonical_type(t) for t in (types or ()))
        return base if not types else base + '__' + '__'.join(self.type_symbol_suffix(t) for t in types)

    def infer_expr_type(self, expr, scope=None, current_class=None):
        scope = scope or {}
        e = str(expr or '').strip()
        if not e:
            return 'Void'
        m = re.match(r'^\(\s*([A-Za-z_][\w:<>\s,*&]*)\s*\)', e)
        if m:
            return self.canonical_type(m.group(1))
        if e in scope:
            return self.canonical_type(scope[e])
        se = self.safe_name(e)
        if se in scope:
            return self.canonical_type(scope[se])
        if e == 'This' or e == 'this':
            return (current_class or 'Void') + '*'
        if e.startswith('&'):
            inner = e[1:].strip()
            return self.canonical_type(scope.get(inner) or scope.get(self.safe_name(inner)) or 'Void') + '*'
        if re.match(r'^"', e):
            return 'Char*'
        if re.match(r"^'", e):
            return 'Char'
        if re.match(r'^[0-9]+[uU]?[lL]{1,2}$', e):
            return 'I64'
        if re.match(r'^0[xX][0-9A-Fa-f]+', e):
            return 'I32'
        if re.match(r'^[0-9]+$', e):
            return 'I32'
        if re.match(r'^[0-9]*\.[0-9]+[fF]$', e):
            return 'Float'
        if re.match(r'^[0-9]*\.[0-9]+', e):
            return 'Double'
        m = re.match(r'^New\s+([A-Za-z_]\w*(?:\s*<\s*[^<>]+\s*>)?)', e)
        if m:
            return self.c_type(m.group(1)).replace('*','').strip() + '*'
        # For compound expressions, prefer a wider numeric type if any operand is wider.
        parts = re.split(r'\s*[+\-*/%&|^<>]=?|&&|\|\|\s*', e)
        inferred = [self.infer_expr_type(x, scope, current_class) for x in parts if x and x != e]
        if inferred:
            if any(self.canonical_type(x) in {'Double','Ldouble'} for x in inferred): return 'Double'
            if any(self.canonical_type(x) == 'Float' for x in inferred): return 'Float'
            if any(self.canonical_type(x) in {'I64','U64'} for x in inferred): return 'I64'
            return inferred[0]
        return 'I32'

    def ctor_type_compatible(self, expected, actual):
        e = self.canonical_type(expected); a = self.canonical_type(actual)
        if e == a:
            return True
        int_types = {'I16','I32','I64','U16','U32','U64','Char','Uchar','Boolean'}
        float_types = {'Float','Double','Ldouble'}
        if e in int_types and a in int_types:
            return True
        if e in float_types and a in float_types | int_types:
            return True
        if e.endswith('*') and a in {'Null','Void*'}:
            return True
        return False

    def resolve_constructor(self, cls, arg_text, scope=None, current_class=None):
        cname = self.safe_name(cls)
        args = self.split_expr_args(arg_text or '')
        actual = tuple(self.canonical_type(self.infer_expr_type(a, scope, current_class)) for a in args)
        entries = self.ctor_signatures.get(cname) or []
        for types, m in entries:
            if tuple(types) == actual:
                return types, m, args
        count_matches = [(types, m) for types, m in entries if len(types) == len(actual)]
        compatible = [(types, m) for types, m in count_matches if all(self.ctor_type_compatible(t, a) for t, a in zip(types, actual))]
        if len(compatible) == 1:
            return compatible[0][0], compatible[0][1], args
        if len(count_matches) == 1:
            return count_matches[0][0], count_matches[0][1], args
        for types, m in entries:
            if len(types) == 0 and len(actual) == 0:
                return types, m, args
        return tuple(actual), None, args

    # ---------- virtual dispatch metadata ----------
    def build_virtual_metadata(self, classes):
        by_name = {self.safe_name(c.name): c for c in classes}
        self.virtual_slot_maps = {}
        self.virtual_impl_symbols = {}
        self.virtual_method_sigs = {}
        for c in classes:
            cname = self.safe_name(c.name)
            slot_map = {}
            impls = []
            sigs = {}
            if c.base:
                bname = self.safe_name(c.base)
                slot_map.update(self.virtual_slot_maps.get(bname, {}))
                inherited_impls = self.virtual_impl_symbols.get(bname, [])
                impls = list(inherited_impls)
                sigs.update(self.virtual_method_sigs.get(bname, {}))
            local_methods = {m.name: m for m in c.methods if not (m.constructor or m.destructor)}
            for m in c.methods:
                if m.constructor or m.destructor:
                    continue
                is_virtual = m.pure_virtual or 'Overridable' in m.decorators or m.name in slot_map
                if not is_virtual:
                    continue
                if m.name not in slot_map:
                    slot_map[m.name] = len(slot_map)
                    impls.append('(CMotiveMethodSlot)CMotive_PureVirtual')
                sigs.setdefault(m.name, m)
                idx = slot_map[m.name]
                if len(impls) <= idx:
                    impls.extend(['(CMotiveMethodSlot)CMotive_PureVirtual'] * (idx + 1 - len(impls)))
                if not m.pure_virtual:
                    impls[idx] = f'(CMotiveMethodSlot){self.c_name(m)}'
                    sigs[m.name] = sigs.get(m.name) or m
            if slot_map:
                c.has_virtuals = True
                self.virtual_slot_maps[cname] = slot_map
                self.virtual_impl_symbols[cname] = impls
                self.virtual_method_sigs[cname] = sigs
            else:
                c.has_virtuals = False

    def vtable_block(self, classes):
        lines = []
        for c in classes:
            cname = self.safe_name(c.name)
            slots = self.virtual_impl_symbols.get(cname)
            if not slots:
                continue
            prefix = self.class_symbol_prefix(cname, getattr(c, 'package', DEFAULT_PACKAGE))
            arr = f'{prefix}__vslots'
            vt = f'{prefix}__vtable'
            lines.append(f'static CMotiveMethodSlot {arr}[] = {{ ' + ', '.join(slots) + ' };')
            lines.append(f'static CMotiveVTable {vt} = {{ {arr}, {len(slots)} }};')
            lines.append('')
        return lines

    # ---------- Target/Hit dispatch metadata ----------
    def normalize_hit_sender(self, sender):
        sender = str(sender or '').strip()
        return self.safe_name(sender) if sender else ''

    def normalize_hit_id(self, hit_id):
        return re.sub(r'\s+', '', str(hit_id or '').strip())

    def collect_hit_handlers(self, free_functions, classes):
        self.hit_handlers = {}
        self.dynamic_structs = {}
        self.operator_symbols = {'+':'Plus','-':'Minus','*':'Multiply','/':'Divide','%':'Modulo','==':'Equal','!=':'NotEqual','<':'Less','>':'Greater','<=':'LessEqual','>=':'GreaterEqual','<<':'LeftShift','>>':'RightShift','>>>':'RightRotate','<<<':'LeftRotate','&':'BitAnd','|':'BitOr','^':'BitXor'}
        def add(fn):
            hid = getattr(fn, 'hit_id', None)
            if hid is None or str(hid).strip() == '':
                return
            key = (self.normalize_hit_sender(getattr(fn, 'hit_sender', '')), self.normalize_hit_id(hid))
            if key in self.hit_handlers:
                old = self.hit_handlers[key]
                raise ValueError('duplicate Hit handler for sender %r id %r: %s and %s' % (key[0], key[1], self.c_name(old), self.c_name(fn)))
            self.hit_handlers[key] = fn
        for fn in free_functions:
            add(fn)
        for cls in classes:
            for method in cls.methods:
                add(method)

    def hit_id_as_uint64(self, hit_id):
        text = self.normalize_hit_id(hit_id)
        if not text:
            return '0ULL'
        if re.fullmatch(r'0[xX][0-9A-Fa-f]+|[0-9]+[uUlL]*', text):
            return text
        return '(uint64_t)0ULL'

    def target_receiver_for_method(self, object_expr, handler, scope=None, current_class=None):
        target_class = self.safe_name(handler.method_of or '')
        obj = str(object_expr or '').strip()
        if not obj:
            if current_class and self.safe_name(current_class) == target_class:
                return 'this'
            return None
        if obj in {'This', 'this'}:
            return 'this'
        cexpr = self.expr(obj, scope=scope, current_class=current_class)
        raw_typ = (scope or {}).get(obj) or (scope or {}).get(self.safe_name(obj)) or ''
        cls, is_ptr, is_class = self.class_type_info(raw_typ)
        if is_class and is_ptr:
            return cexpr
        if is_class and not is_ptr:
            return '&' + cexpr
        # Unknown expressions are treated as object lvalues unless they already
        # look like an address, pointer dereference, or call result.  This keeps
        # Target lowering permissive for externally-provided objects while still
        # generating ordinary C.
        if cexpr.startswith('&') or '->' in cexpr or cexpr.endswith(')'):
            return cexpr
        return '&' + cexpr

    def target_stmt(self, s, scope=None, current_class=None):
        sender = self.normalize_hit_sender(s.sender)
        hit_id = self.normalize_hit_id(s.hit_id)
        handler = self.hit_handlers.get((sender, hit_id))
        if handler is None and sender:
            # Sender-qualified Target requires a matching sender-qualified Hit.
            # The empty-sender fallback is intentionally not used because
            # Target Sender::args:id and Target ::args:id are distinct routes.
            pass
        if handler is None:
            return [f'CMotive_UnresolvedTarget({self.c_string(sender)}, {self.hit_id_as_uint64(hit_id)});']
        arg_values = [self.expr(a, scope=scope, current_class=current_class) for a in self.split_expr_args(s.args)]
        if handler.method_of:
            recv = self.target_receiver_for_method(s.object_expr, handler, scope, current_class)
            if recv is None:
                return [f'CMotive_UnresolvedTarget({self.c_string(sender)}, {self.hit_id_as_uint64(hit_id)});']
            call_args = [recv] + arg_values
        else:
            call_args = arg_values
        return [f'{self.c_name(handler)}(' + ', '.join(call_args) + ');']

    # ---------- debug-symbol metadata ----------
    def cmotive_type_text(self, type_name):
        return self.normalize_type_string(type_name or 'Void')

    def cmotive_param_text(self, params):
        if not params:
            return ''
        return ', '.join(f'{self.safe_name(p.name)}: {self.cmotive_type_text(p.type_name)}' for p in params)

    def cmotive_prototype(self, f):
        pkg = self.package_name(getattr(f, 'package', DEFAULT_PACKAGE))
        params = self.cmotive_param_text(getattr(f, 'params', []) or [])
        if f.constructor:
            cls = self.safe_name(f.method_of or f.name)
            return f'{pkg}::{cls}::{cls}({params})'
        if f.destructor:
            cls = self.safe_name(f.method_of or f.name)
            return f'{pkg}::{cls}::~{cls}({params})'
        ret = self.cmotive_type_text(f.return_type)
        if f.method_of:
            return f'{ret} {pkg}::{self.safe_name(f.method_of)}::{self.safe_name(f.name)}({params})'
        return f'{ret} {pkg}::{self.safe_name(f.name)}({params})'

    def debug_symbol_record(self, symbol, kind, prototype, c_prototype='', package=None, class_name='', source=''):
        return {
            'symbol': symbol,
            'kind': kind,
            'package': self.package_name(package or DEFAULT_PACKAGE),
            'class': self.safe_name(class_name) if class_name else '',
            'prototype': prototype,
            'c_prototype': c_prototype,
            'source': source,
        }

    def build_debug_symbols(self, all_functions, all_classes):
        records = []
        seen = set()
        def add(record):
            key = record.get('symbol')
            if not key or key in seen:
                return
            seen.add(key)
            records.append(record)
        for f in all_functions:
            if getattr(f, 'pure_virtual', False) or 'Fptr' in getattr(f, 'decorators', []):
                continue
            kind = 'entry' if f.name == 'main' and not f.method_of else 'function'
            add(self.debug_symbol_record(
                self.c_name(f), kind, self.cmotive_prototype(f),
                self.function_signature(f) + ';', getattr(f, 'package', DEFAULT_PACKAGE), '', ''))
        for c in all_classes:
            for m in c.methods:
                if getattr(m, 'pure_virtual', False):
                    continue
                kind = 'constructor' if m.constructor else ('destructor' if m.destructor else 'method')
                add(self.debug_symbol_record(
                    self.c_name(m), kind, self.cmotive_prototype(m),
                    self.function_signature(m) + ';', getattr(m, 'package', DEFAULT_PACKAGE), c.name, ''))
            for m in [x for x in c.methods if x.constructor]:
                types = tuple(self.canonical_type(p.type_name) for p in m.params)
                sig = self.new_helper_signature(c, m)
                add(self.debug_symbol_record(
                    self.new_name_for_types(self.safe_name(c.name), types), 'new-helper',
                    f'{self.class_package(c.name)}::{self.safe_name(c.name)} New({self.cmotive_param_text(m.params)})',
                    sig + ';', getattr(c, 'package', DEFAULT_PACKAGE), c.name, ''))
            sig = self.delete_helper_signature(c)
            add(self.debug_symbol_record(
                self.delete_name(self.safe_name(c.name)), 'delete-helper',
                f'Void {self.class_package(c.name)}::{self.safe_name(c.name)}::Delete(This)',
                sig + ';', getattr(c, 'package', DEFAULT_PACKAGE), c.name, ''))
            for af in self.auto_fields(c):
                getter = self.auto_get_name(c, af)
                setter = self.auto_set_name(c, af)
                add(self.debug_symbol_record(getter, 'auto-get', f'{self.cmotive_type_text(af.type_name)} {self.class_package(c.name)}::{self.safe_name(c.name)}::Get@{self.safe_name(af.name)}()', '', getattr(c, 'package', DEFAULT_PACKAGE), c.name, ''))
                add(self.debug_symbol_record(setter, 'auto-set', f'Void {self.class_package(c.name)}::{self.safe_name(c.name)}::Set@{self.safe_name(af.name)}(value: {self.cmotive_type_text(af.type_name)})', '', getattr(c, 'package', DEFAULT_PACKAGE), c.name, ''))
            if self.auto_fields(c):
                add(self.debug_symbol_record(self.auto_getall_name(c), 'auto-getall', f'{self.auto_public_struct_name(c)} {self.class_package(c.name)}::{self.safe_name(c.name)}::Getall()', '', getattr(c, 'package', DEFAULT_PACKAGE), c.name, ''))
                add(self.debug_symbol_record(self.auto_setall_name(c), 'auto-setall', f'Void {self.class_package(c.name)}::{self.safe_name(c.name)}::Setall(...)', '', getattr(c, 'package', DEFAULT_PACKAGE), c.name, ''))
        return records

    # ---------- C emission ----------
    def class_decl(self, c):
        cname = self.safe_name(c.name)
        lines = [f'typedef struct {cname} {{']
        if c.base:
            bname = self.safe_name(c.base)
            lines.append(f'  {bname} __base;')
        else:
            lines.append('  CMotiveObject __cmotive_object;')
        for f in c.fields:
            lines += self.field_decl(f)
        lines += [f'}} {cname};', '']
        auto_fields = self.auto_fields(c)
        if auto_fields:
            data_name = self.auto_public_struct_name(c)
            lines.append(f'typedef struct {data_name} {{')
            for af in auto_fields:
                lines.append('  ' + self.c_decl(af.type_name, self.safe_name(af.name)) + ';')
            lines += [f'}} {data_name};', '']
        for n in c.nested:
            lines += self.class_decl(n)
        return lines

    def field_decl(self, f):
        if getattr(f, 'bit_fields', None):
            bits = ['  struct {']
            for count, name in f.bit_fields:
                bits.append(f'    unsigned int {self.safe_name(name)}:{int(count)};')
            bits.append(f'  }} {self.safe_name(f.name)};')
            return bits
        return ['  ' + self.c_decl(f.type_name, self.safe_name(f.name)) + ';']

    def prototype_block(self, free_functions, classes):
        lines = []
        seen = set()
        for f in free_functions:
            if f.pure_virtual:
                continue
            if 'Fptr' in getattr(f, 'decorators', []):
                for proto in self.fptr_typedefs(f):
                    if proto not in seen:
                        lines.append(proto); seen.add(proto)
                continue
            proto = self.function_signature(f) + ';'
            if proto not in seen:
                lines.append(proto); seen.add(proto)
        for c in classes:
            for m in c.methods:
                if m.pure_virtual:
                    continue
                proto = self.function_signature(m) + ';'
                if proto not in seen:
                    lines.append(proto); seen.add(proto)
            for proto in self.auto_getset_prototypes(c):
                if proto not in seen:
                    lines.append(proto); seen.add(proto)
            for m in [x for x in c.methods if x.constructor]:
                proto = self.new_helper_signature(c, m) + ';'
                if proto not in seen:
                    lines.append(proto); seen.add(proto)
            dproto = self.delete_helper_signature(c) + ';'
            if dproto not in seen:
                lines.append(dproto); seen.add(dproto)
        return lines + [''] if lines else []

    def global_symbol_name(self, v):
        return f'{self.package_name(getattr(v, "package", DEFAULT_PACKAGE))}__{self.safe_name(v.name)}'

    def global_var(self, v):
        prev = self.current_package_context
        self.current_package_context = getattr(v, 'package', DEFAULT_PACKAGE)
        try:
            sym = self.global_symbol_name(v)
            alias = self.safe_name(v.name)
            lines = [self.c_decl(v.type_name, sym) + ' = ' + self.expr(v.value, v.type_name) + ';']
            # A Global variable is package-scoped but source-visible by its declared name.
            # The macro alias keeps existing expressions simple while the emitted symbol
            # remains package-qualified for linker/object isolation.
            if alias != sym:
                lines += [f'#ifndef {alias}', f'#define {alias} {sym}', '#endif']
            lines.append('')
            return lines
        finally:
            self.current_package_context = prev

    def safe_name(self, name):
        if not name:
            return '_cmotive_unnamed'
        name = str(name).replace('$','__')
        name = name.replace('::', '_')
        name = re.sub(r'\W', '_', name)
        name = name.strip('_') or '_cmotive_unnamed'
        if name in {'class','struct','void','int','long','short','switch','case','default','if','else','while','for','do','return','break','continue'}:
            return 'cmotive_' + name
        return name

    def package_name(self, package=None):
        return self.safe_name(package or DEFAULT_PACKAGE)

    def lookup_class(self, class_name):
        if not class_name:
            return None
        return self.class_map.get(class_name) or self.class_map.get(self.safe_name(class_name))

    def class_package(self, class_name, fallback=None):
        cls = self.lookup_class(class_name)
        return getattr(cls, 'package', None) or fallback or DEFAULT_PACKAGE

    def class_symbol_prefix(self, class_name, package=None):
        return f'{self.package_name(package or self.class_package(class_name))}__{self.safe_name(class_name)}'

    def method_name(self, class_name, method_name, package=None):
        return f'{self.class_symbol_prefix(class_name, package)}__{self.safe_name(method_name)}'

    def constructor_name(self, class_name, argc_or_types=(), package=None):
        if isinstance(argc_or_types, int):
            types = tuple('I32' for _ in range(argc_or_types))
            return self.constructor_name_for_types(class_name, types, package)
        return self.constructor_name_for_types(class_name, argc_or_types, package)

    def new_name(self, class_name, argc_or_types=(), package=None):
        if isinstance(argc_or_types, int):
            types = tuple('I32' for _ in range(argc_or_types))
            return self.new_name_for_types(class_name, types, package)
        return self.new_name_for_types(class_name, argc_or_types, package)

    def destructor_name(self, class_name, package=None):
        return f'{self.class_symbol_prefix(class_name, package)}__dtor'

    def delete_name(self, class_name, package=None):
        return f'{self.class_symbol_prefix(class_name, package)}__delete'

    def c_name(self, f):
        if f.name == 'main' and not f.method_of:
            return 'main'
        pkg = getattr(f, 'package', DEFAULT_PACKAGE)
        if f.constructor:
            return self.constructor_name_for_types(f.method_of or f.name, [p.type_name for p in f.params], pkg)
        if f.destructor:
            return self.destructor_name(f.method_of or f.name, pkg)
        if f.method_of:
            return self.method_name(f.method_of, f.name, pkg)
        return f'{self.package_name(pkg)}__{self.safe_name(f.name)}'

    def c_decl(self, type_name, name):
        base, suffix = self.split_array_type(type_name)
        ctype = self.c_type(base)
        return f'{ctype} {name}{suffix}'

    def split_array_type(self, type_name):
        t = type_name or 'I32'
        arrays = ''.join(re.findall(r'\[[^\]]*\]', t))
        t = re.sub(r'\s*\[[^\]]*\]', '', t).strip()
        return t, arrays

    def normalize_type_string(self, t):
        s = str(t or '').strip()
        s = s.replace(' :: ', '::')
        s = re.sub(r'\s*::\s*', '::', s)
        s = re.sub(r'\s*<\s*', '<', s)
        s = re.sub(r'\s*>\s*', '>', s)
        s = re.sub(r'\s*,\s*', ',', s)
        s = re.sub(r'\s*\*\s*', '*', s)
        s = re.sub(r'\s*&\s*', '&', s)
        return s

    def type_template_to_c(self, t):
        s = self.normalize_type_string(t)
        pattern = re.compile(r'\b([A-Za-z_]\w*)<([^<>]+)>')
        while True:
            m = pattern.search(s)
            if not m:
                break
            name = m.group(1); args = self.split_template_args(m.group(2))
            inst = self.template_instance_name(name, args)
            s = s[:m.start()] + inst + s[m.end():]
        return s

    def c_type(self, type_name):
        if not type_name:
            return 'int32_t'
        t = self.type_template_to_c(type_name)
        thread_local = bool(re.search(r'\b(?:Tstore|ThreadStore)\b', t))
        t = re.sub(r'\b(?:Tstore|ThreadStore)\b', '', t).strip()
        t = re.sub(r'\bGlobal\b', '', t).strip()
        t = re.sub(r'\bConst\b', 'const', t)
        t = re.sub(r'\bVolatile\b', 'volatile', t)
        ptr = ''
        while t.endswith('*') or t.endswith('&'):
            ptr = ('*' if t[-1] == '*' else '*') + ptr
            t = t[:-1].strip()
        t = t.replace(' :: ', '::').replace('::', '_')
        parts = t.split()
        mapped = []
        for p in parts:
            mapped.append(TYPE_MAP.get(p, p))
        base = ' '.join(mapped) if mapped else 'int32_t'
        if base == 'void' and ptr:
            out = 'void ' + ptr
        else:
            out = (base + (' ' + ptr if ptr else '')).strip()
        if thread_local:
            out = 'static _Thread_local ' + out
        return out

    def has_top_level_pointer(self, type_name):
        t = self.normalize_type_string(type_name)
        depth = 0
        top = []
        for ch in t:
            if ch == '<':
                depth += 1
            elif ch == '>':
                depth = max(0, depth - 1)
            elif depth == 0:
                top.append(ch)
        return '*' in ''.join(top) or '&' in ''.join(top)

    def class_type_info(self, type_name):
        t = self.normalize_type_string(type_name)
        is_ptr = self.has_top_level_pointer(t)
        base = self.c_type(t).replace('*', '').strip()
        return base, is_ptr, base in self.known_classes


    def auto_fields(self, c):
        return [f for f in getattr(c, 'fields', []) if getattr(f, 'visibility', 'Public') == 'Public' and not getattr(f, 'block_getset', False) and not getattr(f, 'bit_fields', None)]

    def auto_public_struct_name(self, c):
        return self.class_symbol_prefix(self.safe_name(c.name), getattr(c, 'package', DEFAULT_PACKAGE)) + '__PublicData'

    def auto_get_name(self, c, f):
        return self.class_symbol_prefix(self.safe_name(c.name), getattr(c, 'package', DEFAULT_PACKAGE)) + '__Get__' + self.safe_name(f.name)

    def auto_set_name(self, c, f):
        return self.class_symbol_prefix(self.safe_name(c.name), getattr(c, 'package', DEFAULT_PACKAGE)) + '__Set__' + self.safe_name(f.name)

    def auto_getall_name(self, c):
        return self.class_symbol_prefix(self.safe_name(c.name), getattr(c, 'package', DEFAULT_PACKAGE)) + '__Getall'

    def auto_setall_name(self, c):
        return self.class_symbol_prefix(self.safe_name(c.name), getattr(c, 'package', DEFAULT_PACKAGE)) + '__Setall'

    def auto_getset_prototypes(self, c):
        cname = self.safe_name(c.name)
        protos = []
        fields = self.auto_fields(c)
        for f in fields:
            protos.append(f'{self.c_type(f.type_name)} {self.auto_get_name(c, f)}({cname} *this);')
            protos.append(f'void {self.auto_set_name(c, f)}({cname} *this, {self.c_decl(f.type_name, "value")});')
        if fields:
            data = self.auto_public_struct_name(c)
            protos.append(f'{data} {self.auto_getall_name(c)}({cname} *this);')
            args = ', '.join([self.c_decl(f.type_name, self.safe_name(f.name)) for f in fields])
            protos.append(f'void {self.auto_setall_name(c)}({cname} *this' + (', ' + args if args else '') + ');')
        return protos

    def auto_getset_helpers(self, c):
        cname = self.safe_name(c.name)
        fields = self.auto_fields(c)
        lines = []
        for f in fields:
            fname = self.safe_name(f.name)
            lines += [f'{self.c_type(f.type_name)} {self.auto_get_name(c, f)}({cname} *this) {{', f'  return this->{fname};', '}', '']
            lines += [f'void {self.auto_set_name(c, f)}({cname} *this, {self.c_decl(f.type_name, "value")}) {{', f'  this->{fname} = value;', '}', '']
        if fields:
            data = self.auto_public_struct_name(c)
            lines += [f'{data} {self.auto_getall_name(c)}({cname} *this) {{', f'  {data} out;']
            for f in fields:
                fname = self.safe_name(f.name)
                lines.append(f'  out.{fname} = this->{fname};')
            lines += ['  return out;', '}', '']
            args = ', '.join([self.c_decl(f.type_name, self.safe_name(f.name)) for f in fields])
            lines += [f'void {self.auto_setall_name(c)}({cname} *this' + (', ' + args if args else '') + ') {']
            for f in fields:
                fname = self.safe_name(f.name)
                lines.append(f'  this->{fname} = {fname};')
            lines += ['}', '']
        return lines

    def ensure_auto_getset_methods(self, classes):
        # Auto accessors are emitted as generated C helper functions so they do not
        # pollute the user-visible method list or virtual slot metadata.
        return None

    def operation_symbol_name(self, op):
        return self.operator_symbols.get(op, re.sub(r'\W+', '_', str(op)).strip('_') or 'Unknown')

    def operation_method_name(self, op):
        return 'Operation__' + self.operation_symbol_name(op)

    def class_has_method(self, cls, name):
        c = self.lookup_class(cls)
        if not c:
            return False
        return any(m.name == name and not m.constructor and not m.destructor for m in c.methods)

    def fptr_typedefs(self, f):
        ret = self.c_type(f.return_type)
        params = [self.c_decl(p.type_name, self.safe_name(p.name)) for p in f.params]
        param_text = ', '.join(params) if params else 'void'
        pkg_name = f'{self.package_name(getattr(f, "package", DEFAULT_PACKAGE))}__{self.safe_name(f.name)}'
        plain_name = self.safe_name(f.name)
        out = [f'typedef {ret} (*{pkg_name})({param_text});']
        if plain_name != pkg_name:
            out.append(f'typedef {pkg_name} {plain_name};')
        return out

    def function_signature(self, f):
        ret = 'void' if f.constructor or f.destructor else self.c_type(f.return_type)
        if f.name == 'main' and not f.method_of:
            ret = 'int'
        params = []
        if f.method_of:
            params.append(f'{self.safe_name(f.method_of)} *this')
        for p in f.params:
            params.append(self.c_decl(p.type_name, self.safe_name(p.name)))
        param_text = ', '.join(params) if params else 'void'
        return f'{ret} {self.c_name(f)}({param_text})'

    def function(self, f):
        prev_pkg = self.current_package_context
        self.current_package_context = getattr(f, 'package', DEFAULT_PACKAGE)
        try:
            sig = self.function_signature(f)
            ret = sig.split(' ', 1)[0]
            lines = [sig + ' {']
            scope = {}
            current_class = self.safe_name(f.method_of) if f.method_of else None
            if f.method_of:
                scope['this'] = self.safe_name(f.method_of) + '*'
            for p in f.params:
                scope[self.safe_name(p.name)] = p.type_name
                scope[p.name] = p.type_name
            if f.constructor:
                lines += ['  ' + x for x in self.constructor_prelude(f, scope)]
            for s in f.body:
                lines += ['  ' + x for x in self.stmt(s, [], scope, current_class)]
            if f.destructor:
                lines += ['  ' + x for x in self.destructor_postlude(f)]
            if not any(isinstance(s, Return) for s in f.body):
                if ret == 'void': lines.append('  return;')
                else: lines.append('  return 0;')
            lines += ['}', '']
            return lines
        finally:
            self.current_package_context = prev_pkg

    def constructor_prelude(self, f, scope):
        cls = self.class_map.get(self.safe_name(f.method_of or f.name))
        lines = []
        if cls and cls.base:
            b = self.safe_name(cls.base)
            if 0 in self.ctor_arg_counts.get(b, {0}):
                lines.append(f'{self.constructor_name_for_types(b, [])}(&this->__base);')
        if cls and self.virtual_slot_maps.get(self.safe_name(cls.name)):
            lines.append(f'((CMotiveObject*)this)->vtable = &{self.class_symbol_prefix(self.safe_name(cls.name), getattr(cls, 'package', DEFAULT_PACKAGE))}__vtable;')
        if cls:
            for fld in cls.fields:
                if getattr(fld, 'bit_fields', None):
                    continue
                if not fld.initial or fld.initial == '0':
                    continue
                if '[' in (fld.type_name or ''):
                    continue
                lines.append(f'this->{self.safe_name(fld.name)} = {self.expr(fld.initial, fld.type_name, scope, self.safe_name(cls.name))};')
        return lines

    def destructor_postlude(self, f):
        cls = self.class_map.get(self.safe_name(f.method_of or f.name))
        if cls and cls.base:
            return [f'{self.destructor_name(cls.base)}(&this->__base);']
        return []

    def new_helper_signature(self, c, ctor):
        cname = self.safe_name(c.name)
        params = [self.c_decl(p.type_name, self.safe_name(p.name)) for p in ctor.params]
        types = [p.type_name for p in ctor.params]
        return f'{cname} *{self.new_name_for_types(cname, types)}(' + (', '.join(params) if params else 'void') + ')'

    def delete_helper_signature(self, c):
        cname = self.safe_name(c.name)
        return f'void {self.delete_name(cname)}({cname} *this)'

    def new_delete_helpers(self, c):
        cname = self.safe_name(c.name)
        lines = []
        seen = set()
        for ctor in [m for m in c.methods if m.constructor]:
            types = tuple(self.canonical_type(p.type_name) for p in ctor.params)
            if types in seen:
                continue
            seen.add(types)
            args_decl = [self.c_decl(p.type_name, self.safe_name(p.name)) for p in ctor.params]
            args_call = ', '.join([self.safe_name(p.name) for p in ctor.params])
            if args_call:
                args_call = ', ' + args_call
            sig = f'{cname} *{self.new_name_for_types(cname, types)}(' + (', '.join(args_decl) if args_decl else 'void') + ')'
            lines += [sig + ' {', f'  {cname} *this = ({cname}*)CMotive_New(sizeof({cname}));', '  if (!this) return NULL;', f'  {self.constructor_name_for_types(cname, types)}(this{args_call});', '  return this;', '}', '']
        lines += [self.delete_helper_signature(c) + ' {', '  if (!this) return;', f'  {self.destructor_name(cname)}(this);', '  CMotive_Delete(this);', '}', '']
        return lines

    def cleanup_emit(self, cleanup):
        lines = []
        for item in reversed(cleanup or []):
            if isinstance(item, tuple) and item[0] == 'cleanup_mark':
                lines.append(f'CMotive_Cleanup_RunTo({item[1]});')
            elif isinstance(item, tuple) and item[0] == 'exception_frame':
                lines.append(f'CMOTIVE_EXCEPTION_POP({item[1]});')
            elif isinstance(item, str):
                lines.append(f'CMOTIVE_EXCEPTION_POP({item});')
        return lines

    def has_cleanup_mark(self, cleanup):
        return any(isinstance(x, tuple) and x[0] == 'cleanup_mark' for x in (cleanup or []))

    def register_stack_cleanup(self, cls, var_name, cleanup):
        if not self.has_cleanup_mark(cleanup):
            return []
        return [f'CMotive_Cleanup_Push(&{var_name}, (CMotive_CleanupFn){self.destructor_name(cls)});']

    def stmt(self, s, cleanup=None, scope=None, current_class=None):
        cleanup = cleanup or []
        scope = scope if scope is not None else {}
        if isinstance(s, VarDecl): return self.local_var(s, scope, current_class, cleanup)
        if isinstance(s, Return):
            lines = self.cleanup_emit(cleanup)
            lines.append(f'return {self.expr(s.value, scope=scope, current_class=current_class)};' if s.value else 'return;')
            return lines
        if isinstance(s, ExprStmt): return [self.expr_stmt(s.value, scope, current_class)]
        if isinstance(s, If):
            out = [f'if ({self.expr(s.condition, scope=scope, current_class=current_class)}) {{']
            for x in s.then_body: out += ['  ' + y for y in self.stmt(x, cleanup, scope, current_class)]
            out.append('}')
            if s.else_body:
                out.append('else {')
                for x in s.else_body: out += ['  ' + y for y in self.stmt(x, cleanup, scope, current_class)]
                out.append('}')
            return out
        if isinstance(s, While):
            out = [f'while ({self.expr(s.condition, scope=scope, current_class=current_class)}) {{']
            for x in s.body: out += ['  ' + y for y in self.stmt(x, cleanup, scope, current_class)]
            out.append('}')
            return out
        if isinstance(s, DoWhile):
            out = ['do {']
            for x in s.body: out += ['  ' + y for y in self.stmt(x, cleanup, scope, current_class)]
            out.append(f'}} while ({self.expr(s.condition, scope=scope, current_class=current_class)});')
            return out
        if isinstance(s, For):
            out = [f'for ({self.expr(s.header, scope=scope, current_class=current_class)}) {{']
            for x in s.body: out += ['  ' + y for y in self.stmt(x, cleanup, scope, current_class)]
            out.append('}')
            return out
        if isinstance(s, Break): return ['break;']
        if isinstance(s, Continue): return ['continue;']
        if isinstance(s, Throw): return [f'CMotive_Throw({self.stringish(s.value, scope, current_class)});']
        if isinstance(s, TargetStmt): return self.target_stmt(s, scope, current_class)
        if isinstance(s, DynamicStructExpand): return [f'/* Dynamic Struct {self.safe_name(s.name)} expanded at compile time. */']
        if isinstance(s, TryCatch): return self.try_catch(s, cleanup, scope, current_class)
        if isinstance(s, RawStmt): return [self.raw_stmt(s.value, scope, current_class)]
        return ['/* unknown CMotive statement */']

    def try_catch(self, s, cleanup, scope, current_class):
        self._try_id += 1
        n = self._try_id
        frame = f'&__cmotive_ex_{n}'
        mark = f'__cmotive_cleanup_mark_{n}'
        protected_cleanup = cleanup + [('exception_frame', frame), ('cleanup_mark', mark)]
        out = [
            '{',
            f'  CMotive_CleanupEntry *{mark} = __cmotive_cleanup_stack;',
            f'  CMotive_ExceptionFrame __cmotive_ex_{n};',
            f'  __cmotive_ex_{n}.message = NULL;',
            f'  __cmotive_ex_{n}.prev = __cmotive_exception_stack;',
            f'  __cmotive_exception_stack = &__cmotive_ex_{n};',
            f'  int __cmotive_ex_code_{n} = setjmp(__cmotive_ex_{n}.env);',
            f'  if (__cmotive_ex_code_{n} == 0) {{'
        ]
        for x in s.try_body:
            out += ['    ' + y for y in self.stmt(x, protected_cleanup, scope, current_class)]
        out += [f'    CMotive_Cleanup_RunTo({mark});', f'    CMOTIVE_EXCEPTION_POP(&__cmotive_ex_{n});', '  } else {', f'    CMotive_Cleanup_RunTo({mark});', f'    CMOTIVE_EXCEPTION_POP(&__cmotive_ex_{n});', f'    const char *__cmotive_exception_{n} = __cmotive_ex_{n}.message ? __cmotive_ex_{n}.message : "CMotive exception";', f'    int __cmotive_handled_{n} = 0;']
        if s.catches:
            for spec, body in s.catches:
                cond = '1'
                out.append(f'    if (!__cmotive_handled_{n} && ({cond})) {{')
                out.append(f'      __cmotive_handled_{n} = 1;')
                out.append(f'      (void)__cmotive_exception_{n};')
                for x in body:
                    out += ['      ' + y for y in self.stmt(x, cleanup, scope, current_class)]
                out.append('    }')
        out += [f'    if (!__cmotive_handled_{n}) CMotive_Throw(__cmotive_exception_{n});', '  }', '}']
        return out

    def local_var(self, s, scope, current_class, cleanup=None):
        name = self.safe_name(s.name)
        typ = s.type_name or 'I32'
        init = (s.value or '0').strip()
        if getattr(s, 'global_decl', False):
            scope[name] = typ
            scope[s.name] = typ
            return []
        scope[name] = typ
        scope[s.name] = typ
        ctyp = self.c_type(typ)
        if '[' in str(typ) and init in {'', '0'}:
            return [f'{self.c_decl(typ, name)} = {{0}};']
        if self.safe_name(typ) in getattr(self, 'dynamic_structs', {}) and init in {'', '0'}:
            return [f'{self.c_decl(typ, name)} = {{0}};']
        base_typ, is_ptr, is_class = self.class_type_info(typ)
        if re.search(r'\bNew\b', init):
            if is_class:
                if is_ptr:
                    return [f'{self.c_decl(typ, name)} = {self.lower_new_expression(init, typ, scope, current_class)};']
                args = self.extract_new_args(init)[1] if self.extract_new_args(init) else ''
                call = self.call_constructor_for_stack(base_typ, name, args, scope, current_class)
                lines = [f'{self.c_decl(typ, name)} = {{0}};'] + ([call] if call else [])
                lines += self.register_stack_cleanup(base_typ, name, cleanup)
                return lines
            return [f'{self.c_decl(typ, name)} = ({ctyp})CMotive_New(sizeof(CMotiveObject));']
        if is_class and not is_ptr:
            lines = [f'{self.c_decl(typ, name)} = {{0}};']
            call = self.call_constructor_for_stack(base_typ, name, '', scope, current_class)
            if call:
                lines.append(call)
            lines += self.register_stack_cleanup(base_typ, name, cleanup)
            return lines
        if is_class and is_ptr and init in {'', '0'}:
            return [f'{self.c_decl(typ, name)} = NULL;']
        return [f'{self.c_decl(typ, name)} = {self.expr(init, typ, scope, current_class)};']

    def call_constructor_for_stack(self, cls, var_name, args, scope=None, current_class=None):
        cname = self.safe_name(cls)
        types, ctor, arg_list = self.resolve_constructor(cname, args, scope, current_class)
        arg_text = ', '.join(arg_list)
        if not arg_text:
            return f'{self.constructor_name_for_types(cname, types)}(&{var_name});'
        return f'{self.constructor_name_for_types(cname, types)}(&{var_name}, {self.expr(arg_text, scope=scope, current_class=current_class)});'

    def extract_new_args(self, text):
        s = self.normalize_type_string(text)
        m = re.search(r'\bNew\s+([A-Za-z_]\w*(?:<[^<>]+>)?)\s*\((.*)\)\s*$', s)
        if m:
            return self.c_type(m.group(1)).replace('*', '').strip(), m.group(2).strip()
        m = re.search(r'\bNew\s*\((.*)\)\s*$', s)
        if m:
            return None, m.group(1).strip()
        return None

    def lower_new_expression(self, text, declared_type=None, scope=None, current_class=None):
        parsed = self.extract_new_args(text)
        if not parsed:
            return self.expr(text, declared_type, scope, current_class)
        explicit_cls, args = parsed
        declared_base, declared_ptr, declared_is_class = self.class_type_info(declared_type or '')
        cls = explicit_cls or (declared_base if declared_is_class else None)
        if not cls or cls not in self.known_classes:
            return f'CMotive_New(sizeof({cls or "CMotiveObject"}))'
        types, ctor, arg_list = self.resolve_constructor(cls, args, scope, current_class)
        arg_text = ', '.join(arg_list)
        call = f'{self.new_name_for_types(cls, types)}(' + (self.expr(arg_text, scope=scope, current_class=current_class) if arg_text else '') + ')'
        if declared_is_class and declared_base != cls:
            return f'({self.c_type(declared_type)}){call}'
        return call

    def count_call_args(self, arg_text):
        if not arg_text or not str(arg_text).strip():
            return 0
        return len(self.split_expr_args(arg_text))

    def split_expr_args(self, arg_text):
        args, cur, depth, in_str, esc = [], [], 0, False, False
        for ch in str(arg_text):
            if in_str:
                cur.append(ch)
                if esc:
                    esc = False
                elif ch == '\\':
                    esc = True
                elif ch == '"':
                    in_str = False
                continue
            if ch == '"':
                in_str = True; cur.append(ch); continue
            if ch in '([{<': depth += 1
            elif ch in ')]}>': depth -= 1
            if ch == ',' and depth == 0:
                val = ''.join(cur).strip()
                if val: args.append(val)
                cur = []
            else:
                cur.append(ch)
        val = ''.join(cur).strip()
        if val: args.append(val)
        return args

    def expr_stmt(self, text, scope=None, current_class=None):
        e = self.expr(text, scope=scope, current_class=current_class)
        if not e or e == ';': return ';'
        return e if e.rstrip().endswith(';') else e + ';'

    def raw_stmt(self, text, scope=None, current_class=None):
        e = self.translate_keywords(text)
        e = self.expr(e, scope=scope, current_class=current_class)
        return e if e.rstrip().endswith(';') or e.rstrip().endswith('}') else e + ';'

    def c_string(self, text):
        return '"' + str(text or '').replace('\\', '\\\\').replace('"', '\\"') + '"'

    def stringish(self, text, scope=None, current_class=None):
        e = self.expr(text, scope=scope, current_class=current_class)
        if e.startswith('"'):
            return e
        if re.fullmatch(r'[0-9]+', e or ''):
            return '"CMotive numeric exception"'
        return '(const char*)(' + (e or '"CMotive exception"') + ')'

    def cmotive_cast_to_c(self, typename):
        t = typename.strip().replace(' ', '')
        pointer = ''
        while t.endswith('*'):
            pointer += '*'; t = t[:-1]
        mapped = TYPE_MAP.get(t, self.c_type(t))
        if pointer: return mapped + ' ' + pointer
        return mapped

    def lower_typecasts(self, s):
        names = '|'.join(sorted((re.escape(k) for k in TYPE_MAP.keys()), key=len, reverse=True))
        pat = re.compile(r'\(\s*(' + names + r')(\s*\*+)?\s*\)')
        return pat.sub(lambda m: '(' + self.cmotive_cast_to_c((m.group(1) + (m.group(2) or '')).strip()) + ')', s)

    def lower_template_calls(self, s):
        for name, args in self.find_template_uses(s):
            if name in self.templates:
                inst = self.template_instance_name(name, args)
                fn = self.function_instances.get(inst)
                sym = self.c_name(fn) if fn is not None else f'{self.package_name(self.current_package_context)}__{inst}'
                s = re.sub(r'\b' + re.escape(name) + r'\s*<\s*' + re.escape(','.join(args)).replace(',', r'\s*,\s*') + r'\s*>\s*\(', sym + '(', s)
        for (name, args) in list(self.template_use_seen):
            inst = self.template_instance_name(name, list(args))
            fn = self.function_instances.get(inst)
            sym = self.c_name(fn) if fn is not None else f'{self.package_name(self.current_package_context)}__{inst}'
            arg_pat = r'\s*,\s*'.join(re.escape(a).replace('\\ ', r'\s*') for a in args)
            s = re.sub(r'\b' + re.escape(name) + r'\s*<\s*' + arg_pat + r'\s*>\s*\(', sym + '(', s)
        return s

    def resolve_function_symbol(self, name):
        candidates = self.functions_by_name.get(name) or self.functions_by_name.get(self.safe_name(name)) or []
        if not candidates:
            return None
        current_pkg = self.package_name(self.current_package_context)
        for f in candidates:
            if self.package_name(getattr(f, 'package', DEFAULT_PACKAGE)) == current_pkg:
                return self.c_name(f)
        if len(candidates) == 1:
            return self.c_name(candidates[0])
        for f in candidates:
            if self.package_name(getattr(f, 'package', DEFAULT_PACKAGE)) == self.package_name(DEFAULT_PACKAGE):
                return self.c_name(f)
        return self.c_name(candidates[0])

    def lower_known_function_calls(self, s):
        for name in sorted(self.known_functions, key=len, reverse=True):
            safe = self.safe_name(name)
            if not safe or safe == 'main':
                continue
            if name in {'printf','scanf','sprintf','fprintf','fscanf','snprintf','vprintf','vsprintf'}:
                continue
            sym = self.resolve_function_symbol(name)
            if not sym:
                continue
            s = re.sub(r'(?<![\w:.>-])\b' + re.escape(name) + r'\s*\(', sym + '(', s)
        return s

    def virtual_call_prefix(self, cls, method, receiver):
        cname = self.safe_name(cls)
        slot = self.virtual_slot_maps.get(cname, {}).get(method)
        if slot is None:
            return None
        sig = self.virtual_method_sigs.get(cname, {}).get(method)
        ret = self.c_type(sig.return_type) if sig else 'int32_t'
        params = [f'{cname} *']
        if sig:
            params += [self.c_type(p.type_name) for p in sig.params]
        fn_type = ret + ' (*)(' + ', '.join(params) + ')'
        return f'(({fn_type})(((CMotiveObject*)({receiver}))->vtable->slots[{slot}]))({receiver}, '


    def lower_auto_getset_calls(self, s, scope=None, current_class=None):
        scope = scope or {}
        # Add pseudo receiver for This/this.
        work_scope = dict(scope)
        if current_class:
            work_scope.setdefault('this', current_class + '*')
            work_scope.setdefault('This', current_class + '*')
        for var, typ in sorted(work_scope.items(), key=lambda x: len(x[0]), reverse=True):
            cls, is_ptr, is_class = self.class_type_info(typ)
            if not is_class:
                continue
            c = self.lookup_class(cls)
            if not c:
                continue
            recv = var if is_ptr or var in {'this','This'} else '&' + var
            op = r'->' if is_ptr or var in {'this','This'} else r'\.'
            for f in self.auto_fields(c):
                fname = self.safe_name(f.name)
                s = re.sub(r'\b' + re.escape(var) + r'\s*' + op + r'\s*Get\s*@\s*' + re.escape(fname) + r'\s*\(\s*\)', f'{self.auto_get_name(c, f)}({recv})', s)
                s = re.sub(r'\b' + re.escape(var) + r'\s*' + op + r'\s*Set\s*@\s*' + re.escape(fname) + r'\s*\((.*)\)', lambda m, c=c, f=f, recv=recv: f'{self.auto_set_name(c, f)}({recv}, {self.expr(m.group(1), scope=scope, current_class=current_class)})', s)
            if self.auto_fields(c):
                s = re.sub(r'\b' + re.escape(var) + r'\s*' + op + r'\s*Getall\s*\(\s*\)', f'{self.auto_getall_name(c)}({recv})', s)
                s = re.sub(r'\b' + re.escape(var) + r'\s*' + op + r'\s*Setall\s*\((.*)\)', lambda m, c=c, recv=recv: f'{self.auto_setall_name(c)}({recv}' + (', ' + self.expr(m.group(1), scope=scope, current_class=current_class) if m.group(1).strip() else '') + ')', s)
        return s

    def lower_operation_calls(self, s, scope=None, current_class=None):
        scope = scope or {}
        stripped = s.strip()
        # Only lower clear top-level binary expressions. This keeps normal C arithmetic intact.
        for var, typ in sorted(scope.items(), key=lambda x: len(x[0]), reverse=True):
            cls, is_ptr, is_class = self.class_type_info(typ)
            if not is_class:
                continue
            recv = var if is_ptr else '&' + var
            for op in sorted(self.operator_symbols.keys(), key=len, reverse=True):
                method = self.operation_method_name(op)
                if not self.class_has_method(cls, method):
                    continue
                pat = r'^' + re.escape(var) + r'\s*' + re.escape(op) + r'\s*(.+)$'
                m = re.match(pat, stripped)
                if m:
                    rhs = self.expr(m.group(1), scope=scope, current_class=current_class)
                    return f'{self.method_name(cls, method)}({recv}, {rhs})'
        return s

    def lower_method_calls(self, s, scope=None, current_class=None):
        scope = scope or {}
        if current_class:
            cobj = self.class_map.get(current_class, ClassDecl(current_class))
            for m in cobj.methods:
                if m.constructor or m.destructor or m.pure_virtual:
                    continue
                virt = self.virtual_call_prefix(current_class, m.name, 'this')
                repl = virt if virt else f'{self.method_name(current_class, m.name)}(this, '
                s = re.sub(r'\bthis\s*->\s*' + re.escape(m.name) + r'\s*\(', repl, s)
        for var, typ in sorted(scope.items(), key=lambda x: len(x[0]), reverse=True):
            if var == 'this':
                continue
            cls, is_ptr, is_class = self.class_type_info(typ)
            if not is_class:
                continue
            if is_ptr:
                def repl_ptr(m):
                    method = m.group(1)
                    virt = self.virtual_call_prefix(cls, method, var)
                    return virt if virt else f'{self.method_name(cls, method)}({var}, '
                s = re.sub(r'\b' + re.escape(var) + r'\s*->\s*([A-Za-z_]\w*)\s*\(', repl_ptr, s)
            else:
                def repl_obj(m):
                    method = m.group(1)
                    recv = '&' + var
                    virt = self.virtual_call_prefix(cls, method, recv)
                    return virt if virt else f'{self.method_name(cls, method)}(&{var}, '
                s = re.sub(r'\b' + re.escape(var) + r'\s*\.\s*([A-Za-z_]\w*)\s*\(', repl_obj, s)
        s = re.sub(r',\s*\)', ')', s)
        return s

    def lower_member_names(self, s, scope=None, current_class=None):
        if not current_class or current_class not in self.class_map:
            return s
        scope = scope or {}
        cls = self.class_map[current_class]
        local_names = {self.safe_name(k) for k in scope.keys()}
        for fld in cls.fields:
            fname = self.safe_name(fld.name)
            if fname in local_names:
                continue
            s = re.sub(r'(?<![\w.>])\b' + re.escape(fname) + r'\b(?!\s*\()', 'this->' + fname, s)
            s = re.sub(r'->\s*this->' + re.escape(fname) + r'\b', '->' + fname, s)
            s = re.sub(r'\.\s*this->' + re.escape(fname) + r'\b', '.' + fname, s)
        return s

    def lower_delete(self, s, scope=None):
        scope = scope or {}
        def repl(m):
            var = self.safe_name(m.group(1))
            typ = scope.get(var) or scope.get(m.group(1)) or ''
            cls, is_ptr, is_class = self.class_type_info(typ)
            if is_class:
                return f'{self.delete_name(cls)}({var})' if is_ptr else f'{self.destructor_name(cls)}(&{var})'
            return f'CMotive_Delete({var})'
        return re.sub(r'\bDelete\s+([A-Za-z_]\w*)', repl, s)

    def expr(self, e, declared_type=None, scope=None, current_class=None):
        if e is None: return ''
        s = str(e).strip()
        if not s: return ''
        s = self.translate_keywords(s)
        s = re.sub(r'\bTrue\b', '1', s)
        s = re.sub(r'\bFalse\b', '0', s)
        s = re.sub(r'\bNull\b', 'NULL', s)
        s = re.sub(r'\bThis\b', 'this', s)
        s = re.sub(r'\bNot\b', '!', s)
        s = re.sub(r'\bSizeof\b', 'sizeof', s)
        s = re.sub(r'\bsizeof\s*\(\s*([A-Za-z_][\w:<>,\s*&*]*)\s*\)', lambda m: 'sizeof(' + self.c_type(m.group(1).strip()) + ')', s)
        s = self.lower_typecasts(s)
        s = re.sub(r'\bthis\s*\.\s*', 'this->', s)
        s = self.lower_template_calls(s)
        s = self.lower_sys_calls(s)
        s = re.sub(r'cout\s*\.\s*expect\s*\(\s*("(?:\\\\.|[^"])*")\s*\)\s*\.\s*write\s*\((.*)\)\s*$', lambda m: 'printf(' + m.group(1) + ((', ' + m.group(2)) if m.group(2).strip() else '') + ')', s)
        s = re.sub(r'cout\s*\.\s*expect\s*\(\s*("(?:\\\\.|[^"])*")\s*\)\s*\.\s*\((.*)\)\s*$', lambda m: 'printf(' + m.group(1) + ((', ' + m.group(2)) if m.group(2).strip() else '') + ')', s)
        s = re.sub(r'cin\s*\.\s*expect\s*\(\s*("(?:\\\\.|[^"])*")\s*\)\s*\.\s*read\s*\((.*)\)\s*$', lambda m: 'scanf(' + m.group(1) + ((', ' + m.group(2)) if m.group(2).strip() else '') + ')', s)
        s = re.sub(r'\bSys\s*::\s*Stdio\s*::\s*println\s*\(', 'printf(', s)
        s = re.sub(r'\bSys\s*::\s*Stdio\s*::\s*print\s*\(', 'printf(', s)
        s = re.sub(r'\bSys\s*::\s*Logging\s*::\s*info\s*\(', 'cmotive_sys_logging_info(', s)
        s = re.sub(r'\bSys\s*::\s*Logging\s*::\s*error\s*\(', 'cmotive_sys_logging_error(', s)
        s = re.sub(r'\b([A-Za-z_]\w*)\s*>>>\s*([A-Za-z_0-9]+)\b', r'CMOTIVE_ROTR64(\1, \2)', s)
        s = re.sub(r'\b([A-Za-z_]\w*)\s*<<<\s*([A-Za-z_0-9]+)\b', r'CMOTIVE_ROTL64(\1, \2)', s)
        s = self.lower_delete(s, scope)
        if re.search(r'\bNew\b', s):
            parsed = self.extract_new_args(s)
            if parsed and parsed[0] is not None and s.strip().startswith('New'):
                s = self.lower_new_expression(s, declared_type, scope, current_class)
            elif parsed and s.strip().startswith('New'):
                s = self.lower_new_expression(s, declared_type, scope, current_class)
            else:
                s = re.sub(r'\bNew\s+([A-Za-z_]\w*(?:\s*<\s*[^<>]+\s*>)?)\s*\(([^)]*)\)', lambda m: f'{self.new_name_for_types(self.c_type(m.group(1)).replace("*", "").strip(), self.resolve_constructor(self.c_type(m.group(1)).replace("*", "").strip(), m.group(2), scope, current_class)[0])}({m.group(2).strip()})', s)
                s = re.sub(r'\bNew\s*\(([^)]*)\)', 'CMotive_New(sizeof(CMotiveObject))', s)
        s = self.lower_auto_getset_calls(s, scope, current_class)
        s = self.lower_operation_calls(s, scope, current_class)
        s = self.lower_method_calls(s, scope, current_class)
        s = self.lower_member_names(s, scope, current_class)
        s = self.lower_known_function_calls(s)
        s = re.sub(r'([0-9])D\b', r'\1L', s)
        return s

    def translate_keywords(self, s):
        replacements = {
            'Switch':'switch','Case':'case','Default':'default','Break':'break','Continue':'continue',
            'If':'if','Else':'else','Elif':'else if','While':'while','For':'for','Do':'do',
            'Return':'return','Goto':'goto'
        }
        for k, v in replacements.items():
            s = re.sub(r'\b' + k + r'\b', v, s)
        return s
